"""Storage-independent persistence for the audit trail.

`AuditLogService` (see `auditlog.service`) only ever calls `read_all` and
`append` on whatever store it is given -- it never opens a file or checks
a format. Everything about *where* entries live, and which of the two
on-disk shapes they're in, stays behind this seam.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Protocol

from auditlog.archive import normalize_legacy_entries

CURRENT_STORE_VERSION = 2
LEGACY_STORE_VERSION = 1


class EventStore(Protocol):
    """Storage seam the service depends on instead of any concrete format."""

    def read_all(self) -> list[dict]:
        """Return every stored entry as a plain dict, in stored order."""

    def append(self, entry: dict) -> None:
        """Persist one more entry. Existing entries are never touched."""


class ReadOnlyStoreError(Exception):
    """Raised when `append` is called on a store that cannot accept writes."""


class JsonFileEventStore:
    """Current-format (`store_version` 2) log store: one JSON file, append-only."""

    def __init__(self, path: Path) -> None:
        self.path = path

    def read_all(self) -> list[dict]:
        if not self.path.exists():
            return []
        payload = json.loads(self.path.read_text(encoding="utf-8"))
        return list(payload.get("entries", []))

    def append(self, entry: dict) -> None:
        entries = self.read_all()
        entries.append(entry)
        payload = {"store_version": CURRENT_STORE_VERSION, "entries": entries}
        self.path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")


class LegacyArchiveStore:
    """Read-only `store_version` 1 archive.

    Callers always get normalized, current-shape dicts back (see
    `auditlog.archive`) -- never the raw `ref`/`at` shape -- so the rest
    of the service never has to know two formats exist.
    """

    def __init__(self, path: Path) -> None:
        self.path = path

    def read_all(self) -> list[dict]:
        payload = json.loads(self.path.read_text(encoding="utf-8"))
        return normalize_legacy_entries(payload.get("entries", []))

    def append(self, entry: dict) -> None:
        raise ReadOnlyStoreError(f"{self.path} is a legacy archive and cannot be appended to")


def open_store(path: Path) -> EventStore:
    """Sniff `path`'s `store_version` and return the matching store.

    A path that doesn't exist yet is a fresh current-format store: the
    only way to create a `--log-store` is to `record` into it.
    """

    if not path.exists():
        return JsonFileEventStore(path)
    payload = json.loads(path.read_text(encoding="utf-8"))
    version = payload.get("store_version", CURRENT_STORE_VERSION)
    if version == LEGACY_STORE_VERSION:
        return LegacyArchiveStore(path)
    if version == CURRENT_STORE_VERSION:
        return JsonFileEventStore(path)
    raise ValueError(f"unsupported store_version {version!r} in {path}")

"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Stable alias-resolution seam for the host transport."""

from __future__ import annotations


def resolve_v2_alias_catalog(catalog: tuple[tuple[str, str, str, bool | None], ...], canonical_bearer: dict[tuple[str, str], bool]) -> tuple[tuple[str, str, str, bool], ...]:
    """Resolve inherited aliases through their canonical V1 route keys."""

    resolved: list[tuple[str, str, str, bool]] = []
    for method, path, permission, requires_auth in catalog:
        if requires_auth is None:
            canonical_path = path.replace("/v2/", "/v1/", 1)
            requires_auth = canonical_bearer.get((method, canonical_path), True)
        resolved.append((method, path, permission, requires_auth))
    return tuple(resolved)

"""Tests that cohort/phase selection changes only the API version, never auth."""

from __future__ import annotations

import unittest
from pathlib import Path

from auditlog.cohorts import ACTION_ROUTES, bearer_required, load_cohort_phases, route_for

FIXTURES = Path(__file__).parent.parent / "fixtures"


class RouteForTests(unittest.TestCase):
    def test_phase_changes_only_the_path_prefix(self) -> None:
        for action, (method, suffix) in ACTION_ROUTES.items():
            v1_method, v1_path = route_for(action, "v1")
            v2_method, v2_path = route_for(action, "v2")
            self.assertEqual(v1_method, v2_method)
            self.assertEqual(v1_path, f"/v1{suffix}")
            self.assertEqual(v2_path, f"/v2{suffix}")

    def test_routes_match_the_phase_route_expectations_fixture(self) -> None:
        fixture_text = (FIXTURES / "phase-route-expectations.yaml").read_text(encoding="utf-8")
        for action in ACTION_ROUTES:
            for phase in ("v1", "v2"):
                method, path = route_for(action, phase)
                self.assertIn(f"{method} {path}", fixture_text)


class BearerInvariantTests(unittest.TestCase):
    def test_bearer_requirement_is_identical_across_phases(self) -> None:
        for action in ACTION_ROUTES:
            self.assertEqual(bearer_required(action, "v1"), bearer_required(action, "v2"))

    def test_every_action_currently_requires_a_bearer_token(self) -> None:
        for action in ACTION_ROUTES:
            self.assertTrue(bearer_required(action, "v1"))
            self.assertTrue(bearer_required(action, "v2"))


class LoadCohortPhasesTests(unittest.TestCase):
    def test_enabled_cohorts_map_to_their_phase(self) -> None:
        phases = load_cohort_phases(FIXTURES / "upgrade-cohorts.csv")
        self.assertEqual(phases, {"canary-a": "v2", "control-a": "v1"})

    def test_selected_cohorts_agree_on_bearer_requirements(self) -> None:
        phases = load_cohort_phases(FIXTURES / "upgrade-cohorts.csv")
        results = {bearer_required("record", phase) for phase in phases.values()}
        self.assertEqual(results, {True})


if __name__ == "__main__":
    unittest.main()
